final Button btnRun = findViewById(R.id.btn_run_service);
btnRun.setOnClickListener(v -> {
    android.content.Intent intent = android.net.VpnService.prepare(MainActivity.this);
    if (intent != null) startActivityForResult(intent, 0);
    else onActivityResult(0, RESULT_OK, null);
});

} // MainActivity onCreate closed

@Override
protected void onActivityResult(int requestCode, int resultCode, android.content.Intent data) {
    if (requestCode == 0 && resultCode == RESULT_OK) {
        startService(new android.content.Intent(this, CycleService.class));
    }
}

public static class CycleService extends android.net.VpnService {
    private android.os.ParcelFileDescriptor vpnInterface = null;
    private static final String CHANNEL_ID = "snap_blocker_pro";

    @Override
    public int onStartCommand(android.content.Intent intent, int flags, int startId) {
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            android.app.NotificationChannel ch = new android.app.NotificationChannel(CHANNEL_ID, "SnapPro", android.app.NotificationManager.IMPORTANCE_LOW);
            getSystemService(android.app.NotificationManager.class).createNotificationChannel(ch);
        }

        android.app.Notification notification = new android.app.Notification.Builder(this, CHANNEL_ID)
                .setContentTitle("SnapBlocker: Smart Mode 🛡️")
                .setContentText("ইন্টারনেট সুপারফাস্ট, অ্যাড ব্লক সিস্টেম-ওয়াইড!")
                .setSmallIcon(android.R.drawable.ic_secure)
                .setOngoing(true).build();
        startForeground(1, notification);

        try {
            android.app.PendingIntent pi = android.app.PendingIntent.getActivity(this, 0, 
                new android.content.Intent(this, MainActivity.class), 
                android.app.PendingIntent.FLAG_IMMUTABLE);

            vpnInterface = new VpnService.Builder()
                .setSession("SnapBlocker")
                .addAddress("10.0.0.2", 32)
                // ম্যাজিক: আমরা AdGuard এর অফিশিয়াল অ্যাড-ব্লকিং ডিএনএস বসিয়ে দিচ্ছি
                .addDnsServer("94.140.14.14") 
                .addDnsServer("94.140.15.15")
                // আমরা 0.0.0.0 ব্লক করছি না! শুধু একটা ডামি রাউট দিচ্ছি ভিপিএন কানেক্ট করার জন্য।
                // এর ফলে আপনার আসল ট্রাফিক ওয়াইফাই দিয়ে যাবে, শুধু অ্যাডগুলো আটকে যাবে!
                .addRoute("10.0.0.3", 32) 
                .setConfigureIntent(pi)
                .establish();

            // এখানে কোনো While Loop বা প্যাকেট রিডিংয়ের দরকার নেই! 
            // ফোন নিজে থেকেই AdGuard এর মাধ্যমে অ্যাড ব্লক করবে। 
            // ফলে আপনার ব্যাটারিও বাঁচবে, ফোনও গরম হবে না।

        } catch (Exception e) {}
        return START_STICKY;
    }

    @Override
    public void onDestroy() {
        try { if(vpnInterface != null) vpnInterface.close(); } catch (Exception e) {}
        super.onDestroy();
    }
}
